16	// Represents a parsed Spectral ruleset object. Every top-level key other than
17	// "extends" is treated as opaque data and passed through unchanged.
18	type Ruleset = Record<string, unknown> & {
19	  extends?: string[];
20	};
21	
22	// Safety checks for local-file extends entries:
23	// - Depth / cycle guard against infinite recursion.
24	// - Extension check ensures we only load YAML files.
25	// - rootDir guard prevents path traversal (e.g. '../../../etc/passwd') from
26	//   reaching files outside the directory of the originally-selected ruleset.
27	function assertAllowed(absolute: string, visited: Set<string>, depth: number, rootDir: string): void {
28	  if (depth > MAX_EXTENDS_DEPTH) {
29	    throw new Error(`"extends" nested too deeply (max ${MAX_EXTENDS_DEPTH}) at ${absolute}`);
30	  }
31	  if (visited.has(absolute)) {
32	    throw new Error(`"extends" cycle detected at ${absolute}`);
33	  }
34	  if (!ALLOWED_EXTENSIONS.includes(path.extname(absolute).toLowerCase())) {
35	    throw new Error(`"extends" target must be a .yaml or .yml file: ${absolute}`);
36	  }
37	  const rel = path.relative(rootDir, absolute);
38	  if (rel.startsWith('..') || path.isAbsolute(rel)) {
39	    throw new Error(`"extends" target must stay within the ruleset's root directory: ${absolute}`);
40	  }
41	}
