// disk; recompiles when the content changes or the file has been removed externally. Errors thrown by
// compileSpectralRulesetFromContent (invalid YAML, SSRF-blocked hosts, disallowed keys, …) propagate.
export async function writeCompiledRuleset(projectId: string, content: string): Promise<{ compiledPath: string }> {
  const compiledPath = compiledRulesetPathFor(projectId);
  const hash = hashContent(content);

  if (contentHashCache.get(projectId) === hash) {
    try {
      // Content is unchanged; only reuse the cached compile if the file is still present.
      await fs.promises.access(compiledPath);
      return { compiledPath };
    } catch {
      // File was deleted externally (e.g. ENOENT) — fall through to recompile and rewrite.
    }
  }

  const compiled = await compileSpectralRulesetFromContent(content);
  await fs.promises.mkdir(path.dirname(compiledPath), { recursive: true });
  await fs.promises.writeFile(compiledPath, compiled, { encoding: 'utf8' });
  contentHashCache.set(projectId, hash);
  return { compiledPath };
}

// Removes the project's compiled ruleset directory and clears its cache entry so the next
// writeCompiledRuleset call always triggers a full recompile.
export async function deleteCompiledRuleset(projectId: string): Promise<void> {
  const projectDir = path.dirname(compiledRulesetPathFor(projectId));
  await fs.promises.rm(projectDir, { recursive: true, force: true });
  contentHashCache.delete(projectId);
}
